templates.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Unique identifier for the user
  universityId String @unique // University-assigned unique identifier (e.g., student ID)
  email String @unique // User's primary email address
  passwordHash String? // Hashed password for local authentication, null if only SSO is used
  firstName String // User's first name
  lastName String // User's last name
  role String @default("'student'") // User's role (student, faculty, staff, club_admin, platform_admin)
  department String? // User's academic department or staff department
  major String? // Student's major
  interests Json? // Array of user's interests for personalization
  profilePictureUrl String? // URL to user's profile picture
  privacySettings Json? // JSON object for user-specific privacy preferences
  createdAt DateTime // Timestamp when the user account was created
  updatedAt DateTime // Timestamp when the user account was last updated
  status String @default("'active'") // Current status of the user account
}

model Events {
  id String @id @default(uuid()) // Unique identifier for the event
  title String // Title of the event
  description String // Full description of the event
  startTime DateTime // Start date and time of the event
  endTime DateTime // End date and time of the event
  location String // Physical or virtual location of the event
  eventType String @default("'social'") // Category of the event (academic, social, sports, workshop, official)
  organizerId String // ID of the user or club/organization that created the event
  isPublic Boolean @default(true) // Determines if the event is publicly visible to all users
  capacity Int? // Maximum number of attendees, null if unlimited
  imageUrl String? // URL to the event's promotional image
  tags Json? // Array of relevant tags for event discovery
  status String @default("'upcoming'") // Current status of the event (upcoming, live, past, cancelled)
  createdAt DateTime // Timestamp when the event was created
  updatedAt DateTime // Timestamp when the event was last updated

  // Relations:
  // [many-to-one] -> Users (via organizerId) [references]
}

model RSVPs {
  id String @id @default(uuid()) // Unique identifier for the RSVP
  eventId String // ID of the event the user is RSVPing to
  userId String // ID of the user who RSVPed
  status String @default("'attending'") // RSVP status (attending, interested, declined)
  rsvpedAt DateTime // Timestamp when the RSVP was made

  // Relations:
  // [many-to-one] -> Events (via eventId) [references]
  // [many-to-one] -> Users (via userId) [references]
}

model Groups {
  id String @id @default(uuid()) // Unique identifier for the group
  name String @unique // Name of the group
  description String // Description of the group's purpose and activities
  groupType String @default("'interest'") // Type of group (academic, interest, club, department)
  creatorId String // ID of the user who created the group
  isPublic Boolean @default(true) // Determines if the group is publicly discoverable or private
  profilePictureUrl String? // URL to the group's profile picture/logo
  coverImageUrl String? // URL to the group's cover image
  memberCount Int @default(0) // Cached count of group members (updated via triggers/jobs)
  createdAt DateTime // Timestamp when the group was created
  updatedAt DateTime // Timestamp when the group was last updated

  // Relations:
  // [many-to-one] -> Users (via creatorId) [references]
}

model GroupMembers {
  id String @id @default(uuid()) // Unique identifier for the group membership
  groupId String // ID of the group
  userId String // ID of the user who is a member of the group
  role String @default("'member'") // Role of the user within the group (member, admin, moderator)
  joinedAt DateTime // Timestamp when the user joined the group

  // Relations:
  // [many-to-one] -> Groups (via groupId) [references]
  // [many-to-one] -> Users (via userId) [references]
}

model Posts {
  id String @id @default(uuid()) // Unique identifier for the post
  groupId String? // ID of the group this post belongs to (null for campus-wide posts)
  userId String // ID of the user who created the post
  title String? // Title of the post (optional for comments)
  content String // Actual content of the post or comment
  contentType String @default("'text'") // Type of content (text, image, video, document)
  parentPostId String? // ID of the parent post for comments/replies
  createdAt DateTime // Timestamp when the post was created
  updatedAt DateTime // Timestamp when the post was last updated
  status String @default("'published'") // Moderation status of the post (published, draft, moderated, deleted)

  // Relations:
  // [many-to-one] -> Groups (via groupId) [references]
  // [many-to-one] -> Users (via userId) [references]
  // [many-to-one] -> Posts (via parentPostId) [references]
}

model Resources {
  id String @id @default(uuid()) // Unique identifier for the resource
  title String // Title or name of the resource
  description String // Detailed description of the resource
  resourceType String @default("'document'") // Type of resource (document, service, link, contact)
  url String? // URL to the actual resource (e.g., PDF, external website)
  categoryId String // ID of the category this resource belongs to
  department String? // Department or office providing the resource
  tags Json? // Array of keywords for searching and filtering resources
  visibility String @default("'public'") // Access level for the resource (public, authenticated, role_specific)
  createdAt DateTime // Timestamp when the resource was added
  updatedAt DateTime // Timestamp when the resource was last updated

  // Relations:
  // [many-to-one] -> ResourceCategories (via categoryId) [references]
}

model ResourceCategories {
  id String @id @default(uuid()) // Unique identifier for the category
  name String @unique // Name of the resource category (e.g., 'Academic Support', 'Health & Wellness')
  description String? // Description of the category
  parentCategoryId String? // ID of the parent category for hierarchical organization
  createdAt DateTime // Timestamp when the category was created
  updatedAt DateTime // Timestamp when the category was last updated

  // Relations:
  // [many-to-one] -> ResourceCategories (via parentCategoryId) [references]
}

model Conversations {
  id String @id @default(uuid()) // Unique identifier for the conversation
  type String @default("'direct'") // Type of conversation (direct, group)
  name String? // Name of the conversation (for group chats)
  description String? // Optional description for group chats
  creatorId String? // ID of the user who created the group conversation
  createdAt DateTime // Timestamp when the conversation was initiated
  updatedAt DateTime // Timestamp when the conversation was last updated (e.g., last message)

  // Relations:
  // [many-to-one] -> Users (via creatorId) [references]
}

model Messages {
  id String @id @default(uuid()) // Unique identifier for the message
  conversationId String // ID of the conversation this message belongs to
  senderId String // ID of the user who sent the message
  content String // The actual content of the message
  contentType String @default("'text'") // Type of message content (text, image, file, emoji)
  sentAt DateTime // Timestamp when the message was sent
  readAt DateTime? // Timestamp when the message was read by the receiver/group (nullable)
  status String @default("'sent'") // Delivery status of the message (sent, delivered, read)

  // Relations:
  // [many-to-one] -> Conversations (via conversationId) [references]
  // [many-to-one] -> Users (via senderId) [references]
}

