-- Database Type: PostgreSQL
-- Generated locally by ArchitectAI

CREATE TABLE IF NOT EXISTS "users" (
  "id" VARCHAR(255) PRIMARY KEY,
  "universityId" VARCHAR(255) NOT NULL UNIQUE,
  "email" VARCHAR(255) NOT NULL UNIQUE,
  "passwordHash" VARCHAR(255),
  "firstName" VARCHAR(255) NOT NULL,
  "lastName" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL DEFAULT ''student'',
  "department" VARCHAR(255),
  "major" VARCHAR(255),
  "interests" JSONB DEFAULT '[]',
  "profilePictureUrl" VARCHAR(255),
  "privacySettings" JSONB DEFAULT '{}',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "status" VARCHAR(255) NOT NULL DEFAULT ''active''
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_universityId" ON "users" ("universityId");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE INDEX IF NOT EXISTS "idx_users_lastName_firstName" ON "users" ("lastName", "firstName");
CREATE INDEX IF NOT EXISTS "idx_users_role" ON "users" ("role");
CREATE INDEX IF NOT EXISTS "idx_users_interests" ON "users" ("interests");

CREATE TABLE IF NOT EXISTS "events" (
  "id" VARCHAR(255) PRIMARY KEY,
  "title" VARCHAR(255) NOT NULL,
  "description" VARCHAR(255) NOT NULL,
  "startTime" TIMESTAMP NOT NULL,
  "endTime" TIMESTAMP NOT NULL,
  "location" VARCHAR(255) NOT NULL,
  "eventType" VARCHAR(255) NOT NULL DEFAULT ''social'',
  "organizerId" VARCHAR(255) NOT NULL,
  "isPublic" BOOLEAN NOT NULL DEFAULT true,
  "capacity" INTEGER,
  "imageUrl" VARCHAR(255),
  "tags" JSONB DEFAULT '[]',
  "status" VARCHAR(255) NOT NULL DEFAULT ''upcoming'',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_events_startTime_endTime" ON "events" ("startTime", "endTime");
CREATE INDEX IF NOT EXISTS "idx_events_eventType" ON "events" ("eventType");
CREATE INDEX IF NOT EXISTS "idx_events_organizerId" ON "events" ("organizerId");
CREATE INDEX IF NOT EXISTS "idx_events_title" ON "events" ("title");
CREATE INDEX IF NOT EXISTS "idx_events_tags" ON "events" ("tags");

CREATE TABLE IF NOT EXISTS "rsvps" (
  "id" VARCHAR(255) PRIMARY KEY,
  "eventId" VARCHAR(255) NOT NULL,
  "userId" VARCHAR(255) NOT NULL,
  "status" VARCHAR(255) NOT NULL DEFAULT ''attending'',
  "rsvpedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_rsvps_eventId_userId" ON "rsvps" ("eventId", "userId");
CREATE INDEX IF NOT EXISTS "idx_rsvps_userId" ON "rsvps" ("userId");

CREATE TABLE IF NOT EXISTS "groups" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL UNIQUE,
  "description" VARCHAR(255) NOT NULL,
  "groupType" VARCHAR(255) NOT NULL DEFAULT ''interest'',
  "creatorId" VARCHAR(255) NOT NULL,
  "isPublic" BOOLEAN NOT NULL DEFAULT true,
  "profilePictureUrl" VARCHAR(255),
  "coverImageUrl" VARCHAR(255),
  "memberCount" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_groups_name" ON "groups" ("name");
CREATE INDEX IF NOT EXISTS "idx_groups_groupType" ON "groups" ("groupType");
CREATE INDEX IF NOT EXISTS "idx_groups_isPublic" ON "groups" ("isPublic");

CREATE TABLE IF NOT EXISTS "groupmembers" (
  "id" VARCHAR(255) PRIMARY KEY,
  "groupId" VARCHAR(255) NOT NULL,
  "userId" VARCHAR(255) NOT NULL,
  "role" VARCHAR(255) NOT NULL DEFAULT ''member'',
  "joinedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_groupmembers_groupId_userId" ON "groupmembers" ("groupId", "userId");
CREATE INDEX IF NOT EXISTS "idx_groupmembers_userId" ON "groupmembers" ("userId");

CREATE TABLE IF NOT EXISTS "posts" (
  "id" VARCHAR(255) PRIMARY KEY,
  "groupId" VARCHAR(255),
  "userId" VARCHAR(255) NOT NULL,
  "title" VARCHAR(255),
  "content" VARCHAR(255) NOT NULL,
  "contentType" VARCHAR(255) NOT NULL DEFAULT ''text'',
  "parentPostId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "status" VARCHAR(255) NOT NULL DEFAULT ''published''
);

CREATE INDEX IF NOT EXISTS "idx_posts_groupId" ON "posts" ("groupId");
CREATE INDEX IF NOT EXISTS "idx_posts_userId" ON "posts" ("userId");
CREATE INDEX IF NOT EXISTS "idx_posts_parentPostId" ON "posts" ("parentPostId");
CREATE INDEX IF NOT EXISTS "idx_posts_createdAt" ON "posts" ("createdAt");
CREATE INDEX IF NOT EXISTS "idx_posts_content" ON "posts" ("content");

CREATE TABLE IF NOT EXISTS "resources" (
  "id" VARCHAR(255) PRIMARY KEY,
  "title" VARCHAR(255) NOT NULL,
  "description" VARCHAR(255) NOT NULL,
  "resourceType" VARCHAR(255) NOT NULL DEFAULT ''document'',
  "url" VARCHAR(255),
  "categoryId" VARCHAR(255) NOT NULL,
  "department" VARCHAR(255),
  "tags" JSONB DEFAULT '[]',
  "visibility" VARCHAR(255) NOT NULL DEFAULT ''public'',
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_resources_categoryId" ON "resources" ("categoryId");
CREATE INDEX IF NOT EXISTS "idx_resources_resourceType" ON "resources" ("resourceType");
CREATE INDEX IF NOT EXISTS "idx_resources_title" ON "resources" ("title");
CREATE INDEX IF NOT EXISTS "idx_resources_tags" ON "resources" ("tags");

CREATE TABLE IF NOT EXISTS "resourcecategories" (
  "id" VARCHAR(255) PRIMARY KEY,
  "name" VARCHAR(255) NOT NULL UNIQUE,
  "description" VARCHAR(255),
  "parentCategoryId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE UNIQUE INDEX IF NOT EXISTS "idx_resourcecategories_name" ON "resourcecategories" ("name");
CREATE INDEX IF NOT EXISTS "idx_resourcecategories_parentCategoryId" ON "resourcecategories" ("parentCategoryId");

CREATE TABLE IF NOT EXISTS "conversations" (
  "id" VARCHAR(255) PRIMARY KEY,
  "type" VARCHAR(255) NOT NULL DEFAULT ''direct'',
  "name" VARCHAR(255),
  "description" VARCHAR(255),
  "creatorId" VARCHAR(255),
  "createdAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "updatedAt" TIMESTAMP NOT NULL DEFAULT 'NOW()'
);

CREATE INDEX IF NOT EXISTS "idx_conversations_type" ON "conversations" ("type");
CREATE INDEX IF NOT EXISTS "idx_conversations_name" ON "conversations" ("name");

CREATE TABLE IF NOT EXISTS "messages" (
  "id" VARCHAR(255) PRIMARY KEY,
  "conversationId" VARCHAR(255) NOT NULL,
  "senderId" VARCHAR(255) NOT NULL,
  "content" VARCHAR(255) NOT NULL,
  "contentType" VARCHAR(255) NOT NULL DEFAULT ''text'',
  "sentAt" TIMESTAMP NOT NULL DEFAULT 'NOW()',
  "readAt" TIMESTAMP,
  "status" VARCHAR(255) NOT NULL DEFAULT ''sent''
);

CREATE INDEX IF NOT EXISTS "idx_messages_conversationId" ON "messages" ("conversationId");
CREATE INDEX IF NOT EXISTS "idx_messages_senderId" ON "messages" ("senderId");
CREATE INDEX IF NOT EXISTS "idx_messages_sentAt" ON "messages" ("sentAt");

